  1→//! Configuration inheritance resolution.
  2→//!
  3→//! This module handles the `extends:` configuration feature, which allows
  4→//! configs to inherit from remote base configurations.
  5→
  6→use std::collections::HashSet;
  7→use std::time::Duration;
  8→
  9→use anyhow::{anyhow, Result};
 10→
 11→use super::merger::deep_merge_with_leaves;
 12→use super::remote::RemoteFetcher;
 13→use super::schema::{BivvyConfig, ExtendsConfig};
 14→
 15→/// Resolves configuration inheritance chain.
 16→///
 17→/// # Example
 18→///
 19→/// ```no_run
 20→/// use bivvy::config::{BivvyConfig, ExtendsResolver};
 21→///
 22→/// let resolver = ExtendsResolver::new();
 23→///
 24→/// // Resolve a config that extends a remote base
 25→/// let config: BivvyConfig = serde_yaml::from_str(r#"
 26→/// extends:
 27→///   - url: https://example.com/base-config.yml
 28→/// app_name: MyApp
 29→/// "#).unwrap();
 30→///
 31→/// let resolved = resolver.resolve(&config).unwrap();
 32→/// ```
 33→pub struct ExtendsResolver {
 34→    fetcher: RemoteFetcher,
 35→    max_depth: usize,
 36→}
 37→
 38→impl ExtendsResolver {
 39→    /// Create a resolver with default settings.
 40→    pub fn new() -> Self {
 41→        Self {
 42→            fetcher: RemoteFetcher::new(Duration::from_secs(30)),
 43→            max_depth: 10,
 44→        }
 45→    }
 46→
 47→    /// Create a resolver with a custom fetcher.
 48→    pub fn with_fetcher(fetcher: RemoteFetcher) -> Self {
 49→        Self {
 50→            fetcher,
 51→            max_depth: 10,
 52→        }
 53→    }
 54→
 55→    /// Create a resolver with custom max depth.
 56→    pub fn with_max_depth(max_depth: usize) -> Self {
 57→        Self {
 58→            fetcher: RemoteFetcher::default(),
 59→            max_depth,
 60→        }
 61→    }
 62→
 63→    /// Resolve all extends references and merge configs.
 64→    pub fn resolve(&self, config: &BivvyConfig) -> Result<BivvyConfig> {
 65→        self.resolve_with_visited(config, &mut HashSet::new(), 0)
 66→    }
 67→
 68→    fn resolve_with_visited(
 69→        &self,
 70→        config: &BivvyConfig,
 71→        visited: &mut HashSet<String>,
 72→        depth: usize,
 73→    ) -> Result<BivvyConfig> {
 74→        if depth > self.max_depth {
 75→            return Err(anyhow!(
 76→                "Config extends depth exceeds maximum of {}",
 77→                self.max_depth
 78→            ));
 79→        }
 80→
 81→        // If no extends, return config as-is
 82→        let extends = match &config.extends {
 83→            Some(e) if !e.is_empty() => e,
 84→            _ => return Ok(config.clone()),
 85→        };
 86→
 87→        // Convert current config to Value for merging
 88→        let config_value = serde_yaml::to_value(config)?;
 89→
 90→        // Environment override blocks should replace entirely, not field-merge
 91→        let leaf_keys = std::collections::HashSet::from(["environments"]);
 92→
 93→        // Start with empty Value
 94→        let mut merged = serde_yaml::Value::Mapping(serde_yaml::Mapping::new());
 95→
 96→        // Process each base config in order
 97→        for ext in extends {
 98→            // Check for cycles
 99→            if visited.contains(&ext.url) {
100→                return Err(anyhow!("Circular extends detected: {}", ext.url));
101→            }
102→            visited.insert(ext.url.clone());
103→
104→            // Fetch and parse base config
105→            let content = self.fetcher.fetch(&ext.url)?;
106→            let base_config: BivvyConfig = serde_yaml::from_str(&content)?;
107→
108→            // Recursively resolve base's extends
109→            let resolved_base = self.resolve_with_visited(&base_config, visited, depth + 1)?;
110→
111→            // Convert to Value and merge
112→            let base_value = serde_yaml::to_value(&resolved_base)?;
113→            merged = deep_merge_with_leaves(&merged, &base_value, &leaf_keys);
114→        }
115→
116→        // Finally merge the current config on top
117→        let final_value = deep_merge_with_leaves(&merged, &config_value, &leaf_keys);
118→
119→        // Deserialize back to BivvyConfig
120→        let mut final_config: BivvyConfig = serde_yaml::from_value(final_value)?;
121→
122→        // Clear extends from final config (already resolved)
123→        final_config.extends = None;
124→
125→        Ok(final_config)
126→    }
127→
128→    /// Get the maximum extends depth.
129→    pub fn max_depth(&self) -> usize {
130→        self.max_depth
131→    }
