  2→//!
  3→//! Bivvy supports configuration layering where later configs override
  4→//! earlier ones. This module implements the merge semantics.
  5→//!
  6→//! # Merge Rules
  7→//!
  8→//! - Objects are merged recursively
  9→//! - Arrays are replaced entirely (not merged)
 10→//! - Null values in overlay delete the corresponding key from base
 11→//! - Scalars in overlay replace scalars in base
 12→
 13→use std::collections::HashSet;
 14→
 15→use serde_yaml::Value;
 16→
 17→/// Deep merge two YAML values.
 18→///
 19→/// Later values override earlier values at the point of conflict.
 20→/// Objects are merged recursively. Arrays are replaced entirely.
 21→/// Null values in overlay delete the corresponding key from base.
 22→///
 23→/// # Arguments
 24→///
 25→/// * `base` - The base configuration
 26→/// * `overlay` - The overlay configuration (takes precedence)
 27→///
 28→/// # Returns
 29→///
 30→/// A new Value with merged contents
 31→pub fn deep_merge(base: &Value, overlay: &Value) -> Value {
 32→    deep_merge_with_leaves(base, overlay, &HashSet::new())
 33→}
 34→
 35→/// Deep merge two YAML values with leaf-key awareness.
 36→///
 37→/// Like `deep_merge`, but keys in `leaf_keys` get special treatment:
 38→/// the MAP at that key is merged (entries added/replaced), but each
 39→/// entry's VALUE replaces entirely instead of recursing. This is used
 40→/// for `environments` blocks where each environment override should
 41→/// replace as a whole rather than being field-merged with the base.
 42→///
 43→/// Null values at the leaf level delete the corresponding entry.
 44→///
 45→/// # Arguments
 46→///
 47→/// * `base` - The base configuration
 48→/// * `overlay` - The overlay configuration (takes precedence)
 49→/// * `leaf_keys` - Keys whose children should replace rather than merge
 50→pub fn deep_merge_with_leaves(base: &Value, overlay: &Value, leaf_keys: &HashSet<&str>) -> Value {
 51→    match (base, overlay) {
 52→        // Both are mappings: merge recursively
 53→        (Value::Mapping(base_map), Value::Mapping(overlay_map)) => {
 54→            let mut result = base_map.clone();
 55→
 56→            for (key, overlay_value) in overlay_map {
 57→                if overlay_value.is_null() {
 58→                    // Null in overlay = delete from result
 59→                    result.remove(key);
 60→                } else if leaf_keys.contains(key.as_str().unwrap_or("")) {
 61→                    // Leaf key: merge the MAP (add/replace entries) but
 62→                    // each entry's VALUE replaces entirely
 63→                    if let (Some(base_inner), Value::Mapping(overlay_inner)) =
 64→                        (result.get(key).and_then(|v| v.as_mapping()), overlay_value)
 65→                    {
 66→                        let mut merged_inner = base_inner.clone();
 67→                        for (inner_key, inner_value) in overlay_inner {
 68→                            if inner_value.is_null() {
 69→                                merged_inner.remove(inner_key);
 70→                            } else {
 71→                                merged_inner.insert(inner_key.clone(), inner_value.clone());
 72→                            }
 73→                        }
 74→                        result.insert(key.clone(), Value::Mapping(merged_inner));
 75→                    } else {
 76→                        result.insert(key.clone(), overlay_value.clone());
 77→                    }
 78→                } else if let Some(base_value) = base_map.get(key) {
 79→                    // Key exists in both: recurse
 80→                    result.insert(
 81→                        key.clone(),
 82→                        deep_merge_with_leaves(base_value, overlay_value, leaf_keys),
 83→                    );
 84→                } else {
 85→                    // Key only in overlay: insert
 86→                    result.insert(key.clone(), overlay_value.clone());
 87→                }
 88→            }
 89→
 90→            Value::Mapping(result)
 91→        }
 92→
 93→        // Overlay is not a mapping, or base is not a mapping: overlay wins
 94→        (_, overlay) => overlay.clone(),
 95→    }
 96→}
