262→mod tests {
263→    use super::*;
264→    use crate::config::remote::RemoteFetcher;
265→    use httpmock::prelude::*;
266→    use std::fs;
267→    use std::time::Duration;
268→    use tempfile::TempDir;
269→
270→    #[test]
271→    fn discover_finds_project_config() {
272→        let temp = TempDir::new().unwrap();
273→        let bivvy_dir = temp.path().join(".bivvy");
274→        fs::create_dir_all(&bivvy_dir).unwrap();
275→        fs::write(bivvy_dir.join("config.yml"), "app_name: test").unwrap();
276→
277→        let paths = ConfigPaths::discover(temp.path());
278→        assert!(paths.project.is_some());
279→        assert!(paths.has_project_config());
280→    }
281→
282→    #[test]
283→    fn discover_finds_local_overrides() {
284→        let temp = TempDir::new().unwrap();
285→        let bivvy_dir = temp.path().join(".bivvy");
286→        fs::create_dir_all(&bivvy_dir).unwrap();
287→        fs::write(bivvy_dir.join("config.yml"), "").unwrap();
288→        fs::write(bivvy_dir.join("config.local.yml"), "").unwrap();
289→
290→        let paths = ConfigPaths::discover(temp.path());
291→        assert!(paths.project_local.is_some());
292→    }
293→
294→    #[test]
295→    fn discover_returns_none_for_missing_configs() {
296→        let temp = TempDir::new().unwrap();
297→        let paths = ConfigPaths::discover(temp.path());
298→        assert!(paths.project.is_none());
299→        assert!(paths.project_local.is_none());
300→        assert!(!paths.has_project_config());
301→    }
302→
303→    #[test]
304→    fn find_project_root_finds_bivvy_dir() {
305→        let temp = TempDir::new().unwrap();
306→        let subdir = temp.path().join("foo").join("bar");
307→        fs::create_dir_all(&subdir).unwrap();
308→        fs::create_dir_all(temp.path().join(".bivvy")).unwrap();
