  1→//! Status command implementation.
  2→//!
  3→//! The `bivvy status` command shows current setup status.
  4→
  5→use std::collections::HashSet;
  6→use std::path::{Path, PathBuf};
  7→use std::time::Duration;
  8→
  9→use crate::cli::args::StatusArgs;
 10→use crate::config::load_merged_config;
 11→use crate::environment::resolver::ResolvedEnvironment;
 12→use crate::error::{BivvyError, Result};
 13→use crate::requirements::checker::GapChecker;
 14→use crate::requirements::probe::EnvironmentProbe;
 15→use crate::requirements::registry::RequirementRegistry;
 16→use crate::requirements::status::RequirementStatus;
 17→use crate::state::{ProjectId, StateStore, StepStatus};
 18→use crate::ui::theme::BivvyTheme;
 19→use crate::ui::{format_relative_time, hints, OutputMode, StatusKind, UserInterface};
 20→
 21→use super::dispatcher::{Command, CommandResult};
 22→
 23→/// The status command implementation.
 24→pub struct StatusCommand {
 25→    project_root: PathBuf,
 26→    args: StatusArgs,
 27→}
 28→
 29→impl StatusCommand {
 30→    /// Create a new status command.
 31→    pub fn new(project_root: &Path, args: StatusArgs) -> Self {
 32→        Self {
 33→            project_root: project_root.to_path_buf(),
 34→            args,
 35→        }
 36→    }
 37→
 38→    /// Get the project root path.
 39→    pub fn project_root(&self) -> &Path {
 40→        &self.project_root
 41→    }
 42→
 43→    /// Get the command arguments.
 44→    pub fn args(&self) -> &StatusArgs {
 45→        &self.args
 46→    }
 47→
 48→    /// Resolve the target environment using the priority chain.
 49→    fn resolve_environment(&self, config: &crate::config::BivvyConfig) -> ResolvedEnvironment {
 50→        ResolvedEnvironment::resolve_from_config(self.args.env.as_deref(), &config.settings)
 51→    }
 52→}
 53→
 54→impl Command for StatusCommand {
 55→    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
 56→        // Load configuration
 57→        let config = match load_merged_config(&self.project_root) {
 58→            Ok(c) => c,
 59→            Err(BivvyError::ConfigNotFound { .. }) => {
 60→                ui.error("No configuration found. Run 'bivvy init' first.");
 61→                return Ok(CommandResult::failure(2));
 62→            }
 63→            Err(e) => return Err(e),
 64→        };
 65→
 66→        // Apply config default_output when no CLI flag was explicitly set
 67→        if ui.output_mode() == OutputMode::Normal {
 68→            ui.set_output_mode(config.settings.default_output.into());
 69→        }
 70→
 71→        // Get project identity
 72→        let project_id = ProjectId::from_path(&self.project_root)?;
 73→
 74→        // Load state
 75→        let state = StateStore::load(&project_id)?;
 76→
 77→        let theme = BivvyTheme::new();
 78→
 79→        // Resolve environment
 80→        let resolved_env = self.resolve_environment(&config);
 81→
 82→        // Show header: ⛺ AppName — Status
 83→        let app_name = config.app_name.as_deref().unwrap_or("Bivvy Setup");
 84→        ui.message(&format!(
 85→            "\n  {} {} {} {}\n",
 86→            theme.header.apply_to("⛺"),
 87→            theme.highlight.apply_to(app_name),
 88→            theme.dim.apply_to("—"),
 89→            theme.dim.apply_to("Status"),
 90→        ));
 91→
 92→        // Show environment info
 93→        ui.message(&format!(
 94→            "  {} {} ({})",
 95→            theme.key.apply_to("Environment:"),
 96→            theme.highlight.apply_to(&resolved_env.name),
 97→            theme.dim.apply_to(resolved_env.source.to_string()),
 98→        ));
 99→        ui.message("");
100→
101→        // Show last run info with relative time
102→        if let Some(last_run) = state.last_run_record() {
103→            ui.message(&format!(
104→                "  {} {} {} {}",
105→                theme.key.apply_to("Last run:"),
106→                theme.dim.apply_to(format_relative_time(last_run.timestamp)),
107→                theme.dim.apply_to("·"),
108→                theme
109→                    .dim
110→                    .apply_to(format!("{} workflow", last_run.workflow)),
111→            ));
112→            ui.message("");
113→        }
114→
115→        // Show step status
116→        ui.message(&format!("  {}", theme.key.apply_to("Steps:")));
117→
118→        let step_names: Vec<&String> = if let Some(ref step_name) = self.args.step {
119→            if config.steps.contains_key(step_name) {
120→                vec![step_name]
121→            } else {
122→                ui.error(&format!("Unknown step: {}", step_name));
123→                return Ok(CommandResult::failure(1));
124→            }
125→        } else {
126→            config.steps.keys().collect()
127→        };
128→
129→        for step_name in &step_names {
130→            // Check if step is skipped by only_environments
131→            let step_config = config.steps.get(*step_name);
132→            let skipped = step_config
133→                .map(|s| {
134→                    !s.only_environments.is_empty()
135→                        && !s.only_environments.iter().any(|e| e == &resolved_env.name)
136→                })
137→                .unwrap_or(false);
138→
139→            if skipped {
140→                ui.message(&format!(
141→                    "    {} {:<20} {}",
142→                    theme.dim.apply_to("⊘"),
143→                    step_name,
144→                    theme
145→                        .dim
146→                        .apply_to(format!("(skipped in {})", resolved_env.name)),
147→                ));
148→                continue;
149→            }
150→
151→            let step_state = state.get_step(step_name);
152→            let status = step_state.map(|s| s.status).unwrap_or(StepStatus::NeverRun);
153→            let kind = StatusKind::from(status);
154→
155→            // Build the right-side info (duration or relative time)
156→            let right_side = step_state
157→                .and_then(|s| {
158→                    if status == StepStatus::NeverRun {
159→                        return None;
160→                    }
161→                    // Show duration if available, otherwise relative timestamp
162→                    if let Some(ms) = s.duration_ms {
163→                        let d = Duration::from_millis(ms);
164→                        Some(
165→                            theme
166→                                .duration
167→                                .apply_to(crate::ui::format_duration(d))
168→                                .to_string(),
169→                        )
170→                    } else {
171→                        s.last_run
172→                            .map(|ts| theme.dim.apply_to(format_relative_time(ts)).to_string())
173→                    }
174→                })
175→                .unwrap_or_default();
176→
177→            ui.message(&format!(
178→                "    {} {:<20} {}",
179→                kind.styled(&theme),
180→                step_name,
181→                right_side,
182→            ));
183→        }
184→
185→        // Show requirements section
186→        let all_reqs: HashSet<String> = config
187→            .steps
188→            .values()
189→            .flat_map(|s| s.requires.iter().cloned())
190→            .collect();
191→
192→        if !all_reqs.is_empty() {
193→            ui.message("");
194→            ui.message(&format!("  {}", theme.key.apply_to("Requirements:")));
195→
196→            let probe = EnvironmentProbe::run();
197→            let req_registry = RequirementRegistry::new().with_custom(&config.requirements);
198→            let mut gap_checker = GapChecker::new(&req_registry, &probe, &self.project_root);
199→
200→            let mut sorted_reqs: Vec<&str> = all_reqs.iter().map(|s| s.as_str()).collect();
201→            sorted_reqs.sort();
202→
203→            for req_name in sorted_reqs {
204→                let status = gap_checker.check_one(req_name);
205→                let (icon, desc) = format_requirement_status(&theme, &status);
206→                ui.message(&format!("    {} {:<20} {}", icon, req_name, desc));
207→            }
208→        }
209→
210→        // Show recommendations
211→        let never_run: Vec<_> = config
212→            .steps
213→            .keys()
214→            .filter(|s| {
215→                state
216→                    .get_step(s)
217→                    .map(|st| st.status == StepStatus::NeverRun)
218→                    .unwrap_or(true)
219→            })
220→            .cloned()
221→            .collect();
222→
223→        let failed: Vec<_> = config
224→            .steps
225→            .keys()
226→            .filter(|s| {
227→                state
228→                    .get_step(s)
229→                    .map(|st| st.status == StepStatus::Failed)
230→                    .unwrap_or(false)
231→            })
232→            .cloned()
233→            .collect();
234→
235→        if !failed.is_empty() {
236→            ui.message("");
237→            ui.show_hint(&hints::after_failed_run(&failed));
238→        } else if !never_run.is_empty() {
239→            ui.message("");
240→            if never_run.len() == config.steps.len() {
241→                ui.show_hint(hints::all_steps_pending());
242→            } else {
243→                ui.show_hint(&hints::some_steps_pending(&never_run));
244→            }
245→        }
246→
247→        Ok(CommandResult::success())
248→    }
249→}
250→
251→/// Format a requirement status for display.
252→fn format_requirement_status(theme: &BivvyTheme, status: &RequirementStatus) -> (String, String) {
253→    match status {
254→        RequirementStatus::Satisfied => (
255→            theme.success.apply_to("✓").to_string(),
256→            theme.dim.apply_to("available").to_string(),
257→        ),
258→        RequirementStatus::SystemOnly { warning, .. } => (
259→            theme.warning.apply_to("⚠").to_string(),
260→            theme.warning.apply_to(warning).to_string(),
261→        ),
262→        RequirementStatus::Inactive {
263→            manager,
264→            activation_hint,
265→            ..
266→        } => (
267→            theme.warning.apply_to("⚠").to_string(),
268→            theme
269→                .warning
270→                .apply_to(format!("{} not activated ({})", manager, activation_hint))
271→                .to_string(),
272→        ),
273→        RequirementStatus::ServiceDown { start_hint, .. } => (
274→            theme.error.apply_to("✗").to_string(),
275→            theme.error.apply_to(start_hint).to_string(),
276→        ),
277→        RequirementStatus::Missing { install_hint, .. } => {
278→            let hint = install_hint.as_deref().unwrap_or("not installed");
279→            (
280→                theme.error.apply_to("✗").to_string(),
281→                theme.error.apply_to(hint).to_string(),
282→            )
283→        }
284→        RequirementStatus::Unknown => (
285→            theme.dim.apply_to("?").to_string(),
286→            theme.dim.apply_to("unknown requirement").to_string(),
287→        ),
288→    }
289→}
