#### Step 4: Modify `ConfigPaths::discover` to find TOML alternatives

**File**: `/private/var/folders/_q/qzh8_t6s15388qqf3p6n3d200000gp/T/bench-uji3m3e6/src/config/loader.rs`

The three finder functions need to look for `.toml` as an alternative when the `.yml` file does not exist. The priority rule is: **YAML takes precedence over TOML** if both exist. This avoids ambiguity and provides a clear migration path.

```rust
/// Find user's global config at ~/.bivvy/config.yml or ~/.bivvy/config.toml
fn find_user_global() -> Option<PathBuf> {
    let base = dirs::home_dir()?.join(".bivvy");
    let yml_path = base.join("config.yml");
    if yml_path.exists() {
        return Some(yml_path);
    }
    let toml_path = base.join("config.toml");
    if toml_path.exists() {
        return Some(toml_path);
    }
    None
}

/// Find project config at .bivvy/config.yml or .bivvy/config.toml
fn find_project_config(project_root: &Path) -> Option<PathBuf> {
    let bivvy_dir = project_root.join(".bivvy");
    let yml_path = bivvy_dir.join("config.yml");
    if yml_path.exists() {
        return Some(yml_path);
    }
    let toml_path = bivvy_dir.join("config.toml");
    if toml_path.exists() {
        return Some(toml_path);
    }
    None
}

/// Find local overrides at .bivvy/config.local.yml or .bivvy/config.local.toml
fn find_project_local(project_root: &Path) -> Option<PathBuf> {
    let bivvy_dir = project_root.join(".bivvy");
    let yml_path = bivvy_dir.join("config.local.yml");
    if yml_path.exists() {
        return Some(yml_path);
    }
    let toml_path = bivvy_dir.join("config.local.toml");
    if toml_path.exists() {
        return Some(toml_path);
    }
    None
}
```

