```

Modify to detect format and parse accordingly:

```rust
pub fn load_config_value(path: &Path) -> Result<serde_yaml::Value> {
    let content = fs::read_to_string(path).map_err(|e| {
        if e.kind() == std::io::ErrorKind::NotFound {
            BivvyError::ConfigNotFound {
                path: path.to_path_buf(),
            }
        } else {
            BivvyError::Io(e)
        }
    })?;

    let format = ConfigFormat::from_path(path).unwrap_or(ConfigFormat::Yaml);

    match format {
        ConfigFormat::Yaml => {
            serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
                path: path.to_path_buf(),
                message: e.to_string(),
            })
        }
        ConfigFormat::Toml => {
            let toml_val: toml::Value = toml::from_str(&content).map_err(|e| {
                BivvyError::ConfigParseError {
                    path: path.to_path_buf(),
                    message: e.to_string(),
                }
            })?;
            Ok(toml_value_to_yaml_value(&toml_val))
        }
    }
}
```

Note: the `unwrap_or(ConfigFormat::Yaml)` default handles the case where someone passes a file with no extension -- it falls back to YAML parsing (backwards compatible).

**Tests**:
